WITH filtered AS (SELECT *, CONCAT_WS('-', browser, device) AS browser_device_key, COALESCE(browser, 'OTHER') AS resolved_browser FROM sessions WHERE browser IS DISTINCT FROM 'Firefox' AND browser = 'Edge'), gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_burst FROM filtered), sessions_sessions AS (SELECT id, started_at, country, browser_device_key, resolved_browser, SUM(is_new_burst) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, session_id, AVG(session_id) FILTER (WHERE country = 'SG') AS sg_avg_session_id, COUNT(*) FILTER (WHERE country = 'DE') AS de_rows, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, COUNT(*) FILTER (WHERE country = 'DE') AS de_rows_2, SUM(session_id) FILTER (WHERE country = 'SG') AS sg_total_session_id FROM sessions_sessions GROUP BY week_start, session_id ORDER BY week_start
